def process(rows, parameters):
    top = rows[0] if rows else None
    matched = bool(top and top[1] >= 5)
    facts = [f"{top[0]} occurred {top[1]} times in window"] if top else ["No evidence rows in window"]
    return {"matched": matched, "facts": facts, "technique_ids": [], "summary": {"categories": len(rows)}}
